Deployment

Development
# Simple Python server
cd /path/to/2026project
python -m http.server 4100


Production with nginx
server {
    listen 80;
    server_name docs.example.com;

    root /path/to/2026project;

    location / {
        try_files $uri $uri/ =404;
    }

    location /ai-viewer/ {
        alias /path/to/2026project/ai-viewer/;
    }

    location /pdai/ {
        alias /path/to/2026project/pdai/;
    }
}


